// ./src/AboutUs.js
import React from 'react';
import { Link } from 'react-router-dom';
import Footer from './components/Footer';
import ISText from './assets/IronpulseText.png'; // Logo
import HeroImage from './assets/AboutUsHero.jpg'; // Hero background
import TeamImage from './assets/OurTeam.jpg';      // Image for "Our Team"
import ValuesImage from './assets/OurValues.jpg';  // Image for "Our Values"
import LegacyImage from './assets/Legacy.jpg';     // Image for "The Legacy"

export default function AboutUs() {
  const sections = [
    {
      title: "Our Team",
      image: TeamImage,
      content: [
        "We began with a single developer in 2023 — learning, experimenting, and building prototypes without funding or industry connections. Passion and creativity drove everything forward.",
        "Like-minded friends soon joined — a small team of dreamers, developers, and storytellers. Together, we founded Iron Shift to make games with passion and purpose."
      ],
    },
    {
      title: "Our Values",
      image: ValuesImage,
      content: [
        "Unyielding Passion & Creativity: The kind that keeps you up at night and drives you just a little crazy — in the best way possible.",
        "Uniquely Driven Development: Fueled by purpose and curiosity — the spark that makes you wake up each day ready to build something new.",
        "Collaboration & Community: Whether introvert or extrovert, there’s a place here. We grow stronger together.",
        "Relentless Innovation: Determined, bold, and maybe a bit stubborn — we push boundaries until they break."
      ],
    },
    {
      title: "The Legacy",
      image: LegacyImage,
      content: [
        "We aim to prove that passion outlives budget. The experiences we create leave lasting impressions and inspire new ambitions.",
        "We refuse to chase trends or compete with industry giants. It’s all about the craft and the feeling we fell in love with as gamers.",
        "Anyone can make a game, but only the passionate can be great."
      ],
    },
  ];

  return (
    <div className="min-h-screen bg-gray-900 text-gray-100 antialiased font-sans flex flex-col">

      {/* HEADER */}
      <header className="w-full fixed z-50 top-0 left-0 px-6 py-6 flex items-center justify-between bg-gradient-to-b from-black to-transparent">
        <img src={ISText} alt="Logo" className="w-36" />
        <Link
          to="/"
          className="px-4 py-2 text-sm font-bold text-blue-400 hover:text-white"
        >
          Back Home
        </Link>
      </header>

      {/* HERO */}
      <section
        className="pt-28 relative w-full bg-cover bg-center"
        style={{
          backgroundImage: `url(${HeroImage})`,
          minHeight: '60vh',
        }}
      >
        <div className="absolute inset-0 bg-black/70 z-0" />
        <div className="relative z-10 max-w-4xl mx-auto px-6 text-center py-20">
          <h1 className="text-4xl md:text-5xl font-bold mb-4">About Iron Shift</h1>
          <p className="text-gray-300 text-lg">
            Independent game studio based in South Africa, fueled by passion, creativity, and the drive to make unique experiences.
          </p>
        </div>
      </section>

      {/* MAIN CONTENT */}
      <main className="max-w-7xl mx-auto px-6 space-y-24">

        {sections.map((sec, idx) => (
          <section key={idx} className="relative w-full h-auto lg:h-96 rounded-xl overflow-hidden flex flex-col lg:flex-row items-center">
            
            {/* IMAGE HALF */}
            <div className="relative w-full lg:w-1/2 h-64 lg:h-full">
              <img
                src={sec.image}
                alt={sec.title}
                className="absolute inset-0 w-full h-full object-cover -translate-x-8 lg:-translate-x-16"
              />
              {/* Gradient fade to right for text readability */}
              <div className="absolute inset-0 bg-gradient-to-r from-black via-black/40 to-black/0" />
            </div>

            {/* TEXT HALF */}
            <div className="relative w-full lg:w-1/2 px-6 py-12 text-gray-100 z-10">
              <h2 className="text-3xl font-bold mb-4">{sec.title}</h2>
              {sec.content.map((c, i) => (
                <p key={i} className="mb-4 text-lg">{c}</p>
              ))}
            </div>

          </section>
        ))}

      </main>

      {/* FOOTER */}
      <Footer />
    </div>
  );
}
